#!/bin/bash
set -euo pipefail
umask 077
[[ $EUID -eq 0 ]] || { echo '请使用 sudo bash'; exit 1; }
exec 9>/run/football-model-update.lock
flock -n 9 || { echo '更新正在运行'; exit 1; }
test -f /opt/football-web/web.py
test -f /opt/football-github-sync/sync.py
test -f /etc/football-github-sync/token
backup=/var/backups/football-model-view-$(date +%Y%m%d-%H%M%S)
mkdir -p "$backup"
cp -a /opt/football-web "$backup/web"
cp -a /opt/football-github-sync/sync.py "$backup/sync.py"
rollback() {
 echo "更新失败，恢复原网页与同步脚本。备份：$backup"
 cp -a "$backup/web/." /opt/football-web/
 cp -a "$backup/sync.py" /opt/football-github-sync/sync.py
 systemctl disable --now football-model-status.timer 2>/dev/null || true
 systemctl restart football-web.service || true
}
trap rollback ERR
systemctl stop football-github-sync.service
python3 - <<'INSTALL_PY'
import base64,os,grp,py_compile
from pathlib import Path
files={'web.py': '', 'app.js': '', 'prediction_view.py': '', 'publish_model_status.py': '', 'sync.py': ''}
for name,encoded in files.items():
 p=Path('/opt/football-github-sync/sync.py') if name=='sync.py' else Path('/opt/football-web')/name
 temp=p.with_suffix(p.suffix+'.new');temp.write_bytes(base64.b64decode(encoded))
 if name.endswith('.py'):py_compile.compile(str(temp),doraise=True)
 os.chmod(temp,0o640);os.chown(temp,0,grp.getgrnam('footballweb').gr_gid if name!='sync.py' else 0);os.replace(temp,p)
INSTALL_PY
runuser -u postgres -- psql -v ON_ERROR_STOP=1 -d football -c 'GRANT SELECT ON football_v1.predictions TO footballweb;'
cat > /etc/systemd/system/football-model-status.service <<'UNIT'
[Unit]
Description=Publish sanitized football model status
[Service]
Type=oneshot
ExecStart=/usr/bin/python3 /opt/football-web/publish_model_status.py
NoNewPrivileges=true
ProtectHome=true
ProtectSystem=strict
ReadWritePaths=/opt/football-web
UNIT
cat > /etc/systemd/system/football-model-status.timer <<'UNIT'
[Unit]
Description=Refresh football model status every five minutes
[Timer]
OnBootSec=1min
OnUnitActiveSec=5min
[Install]
WantedBy=timers.target
UNIT
systemctl daemon-reload
# Run the existing predictor only; do not retrain or replace the active model.
if ! systemctl start football-predict.service; then
 echo '预测任务报错，页面将展示已有记录；请查看 football-predict 日志。'
fi
systemctl start football-model-status.service
systemctl enable --now football-model-status.timer
systemctl restart football-web.service
python3 - <<'VERIFY_PY'
import json,time,urllib.request
c=json.load(open('/etc/football-web/access.json'))
op=urllib.request.build_opener(urllib.request.ProxyHandler({}))
for attempt in range(10):
 try:
  req=urllib.request.Request('http://127.0.0.1:8787/api/v1/analysis',headers={'Authorization':'Bearer '+c['api_key']})
  with op.open(req,timeout=20) as r:d=json.load(r)
  assert 'model' in d and all('prediction' in m for m in d['matches'])
  print('MODEL_API_OK active='+str(d['model'].get('active'))+' matches='+str(len(d['matches'])))
  from collections import Counter
  print('预测分类：',dict(Counter(m['prediction']['status'] for m in d['matches'])))
  break
 except Exception:
  if attempt==9:raise SystemExit('模型接口验证失败，请查看 football-web 日志')
  time.sleep(1)
VERIFY_PY
trap - ERR
systemctl start --no-block football-github-sync.service
echo 'MODEL_VIEW_UPDATE_OK：网页和分析接口已更新，GitHub 同步已提交。'
echo "原文件备份：$backup"
echo '查看同步：journalctl -u football-github-sync.service -n 15 --no-pager'
echo '查看预测：journalctl -u football-predict.service -n 20 --no-pager'
